namespace Cathode.Dsp;

/// <summary>
///     Measured CPU cost of each block type, in percent of one core at 48 kHz (64-frame blocks, worst type, longest
///     IRs; an amp's cost depends on its model and is measured without one), on the
///     reference machine (macOS 27.0.1, Arm64). Generated by
///     <c>dotnet run -c Release --project tools/Cathode.Bench -- --write</c>; rerun it after adding or changing a block.
/// </summary>
public static class BlockCosts {
    static readonly Dictionary<string, double> Percent = new(StringComparer.Ordinal) {
        ["cab"] = 4.07,
        ["chorus"] = 0.23,
        ["circuitamp"] = 31.12,
        ["compressor"] = 0.36,
        ["crossover"] = 0.53,
        ["delay"] = 0.66,
        ["drive"] = 20.07,
        ["dyndist"] = 1.42,
        ["enhancer"] = 0.30,
        ["fbreturn"] = 0.04,
        ["fbsend"] = 0.04,
        ["filter"] = 0.31,
        ["flanger"] = 0.25,
        ["formant"] = 0.27,
        ["fxloop"] = 0.20,
        ["gate"] = 0.14,
        ["geq"] = 0.05,
        ["irplayer"] = 6.90,
        ["mbcomp"] = 0.44,
        ["megatap"] = 0.46,
        ["mixer"] = 0.10,
        ["multidelay"] = 0.58,
        ["mux"] = 0.04,
        ["nam"] = 0.05,
        ["peq"] = 0.07,
        ["phaser"] = 0.46,
        ["pitch"] = 1.24,
        ["resonator"] = 0.23,
        ["reverb"] = 7.02,
        ["ringmod"] = 0.15,
        ["rotary"] = 0.46,
        ["synth"] = 0.92,
        ["tonematch"] = 1.28,
        ["tonestack"] = 0.18,
        ["tremolo"] = 0.35,
        ["vibe"] = 0.40,
        ["vocoder"] = 1.16,
        ["volpan"] = 0.22,
        ["wah"] = 1.83
    };

    /// <summary>The cost of <paramref name="typeId" />, or null for a block that has not been measured.</summary>
    public static double? Of(string typeId) => Percent.TryGetValue(typeId, out var cost) ? cost : null;
}
